#!/usr/bin/env python3
"""Add fictional Seattle fire-response demo scenarios to an existing ResponseMatch database.

All calls, people, fire units, and dispatch details are fictional. Incident pins use
real Seattle landmarks for map demos; no real fire or emergency is implied. This
script adds rows only; it does not create, drop, or migrate tables.

Run from the database project folder with:
    python3 seed_responsematch_seattle_fire.py
"""
import os
import shutil
import subprocess
import sys

